let banners=document.querySelectorAll(".service-section");addEventListener("DOMContentLoaded",e=>{gsap.set(".service-section",{autoAlpha:1})}),banners.forEach(e=>{let t=e.querySelector(".service-image"),o=e.querySelectorAll(".main-content"),r=gsap.timeline().from(t,{y:20,opacity:0,scale:.9,duration:.6,ease:"power2.out"}).from(o,{y:20,opacity:0,stagger:.15,duration:.5,ease:"power2.out"},"-=0.3");ScrollTrigger.create({trigger:e,start:"top 50%",toggleActions:"play none none none",animation:r})});